const { comment, visibilityType, visibilityValue } = $.input;

if (!comment) throw new Error('comment text is required');

// Convert plain text to ADF, preserving line breaks as separate paragraphs
const paragraphs = comment.split('\n');
const adfContent = paragraphs.map(line => ({
  type: 'paragraph',
  content: line.trim() ? [{ type: 'text', text: line }] : []
}));

const payload = {
  body: {
    type: 'doc',
    version: 1,
    content: adfContent
  }
};

if (visibilityType && visibilityValue) {
  payload.visibility = {
    type: visibilityType,
    value: visibilityValue,
    identifier: visibilityValue
  };
}

return payload;

const resp = $.steps.addComment.response || {};
const issueKey = $.input.issueIdOrKey;

return {
  commentId: resp.id || '',
  issueKey,
  author: resp.author ? resp.author.displayName : '',
  created: resp.created || '',
  visibility: resp.visibility || null,
  success: !!resp.id,
  summary: resp.id
    ? `Added comment ${resp.id} to ${issueKey}`
    : `Failed to add comment to ${issueKey}`
};
